#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Debugs;
using MVZ2.Managers;
using MVZ2.UI.DebugConsole;
using MVZ2Logic.Commands;
using UnityEngine;

namespace MVZ2.DebugConsole
{
    public class DebugConsoleController : MonoBehaviour
    {
        public void Show()
        {
            LoadCommandHistory();
            gameObject.SetActive(true);
            ui.ActivateInputField();
        }
        public void Hide()
        {
            gameObject.SetActive(false);
            historyIndex = -1;
            ui.SetCommand(string.Empty);
        }
        public bool IsActive()
        {
            return gameObject.activeSelf;
        }
        public string[] GetCommandHistory()
        {
            return commandHistory.ToArray();
        }
        public void SetDefaultCommandPlaceholder()
        {
            if (string.IsNullOrEmpty(ui.GetCommand()))
            {
                string str = CommandUtility.COMMAND_CHARACTER.ToString();
                ui.SetCommand(str);
                ui.MoveToCommandEnd(false);
            }
        }
        public void ClearConsole()
        {
            ui.ClearConsole();
        }
        public void Print(string text)
        {
            ui.Print(text);
        }
        private void Awake()
        {
            ui.OnCloseClick += OnCloseCallback;
            ui.OnArrowButtonClick += OnArrowButtonClickCallback;
            ui.OnSubmit += OnSubmitCallback;
            ui.OnInputFieldValueChanged += OnInputFieldValueChangedCallback;
            ui.OnAutoCompleteItemClick += OnAutoCompleteItemClickCallback;
            ui.OnAutoCompleteArrowButtonClick += OnAutoCompleteArrowButtonClickCallback;
            Application.logMessageReceivedThreaded += OnLogReceivedCallback;
        }
        private void Update()
        {
            UpdateUIMargin();

            HandleInputNavigation();
            if (CheckSuggestionDirty())
            {
                UpdateInputFieldSuggestions();
            }
            historyNavigated = false;

            FlushLogs();
        }
        private void OnCloseCallback()
        {
            Hide();
        }
        private void OnArrowButtonClickCallback(bool up)
        {
            if (up)
            {
                NavigateHistory(1);
            }
            else
            {
                NavigateHistory(-1);
            }
        }
        private void OnSubmitCallback(string text)
        {
            if (!string.IsNullOrEmpty(text))
            {
                AddToHistory(text);
                historyIndex = -1;
                Main.DebugManager.ExecuteCommand(text);
            }
            ui.SetCommand(string.Empty);
            ui.MoveToCommandEnd(false);
            HideAutoCompletePanel();
            ui.ActivateInputField();
        }
        private void OnInputFieldValueChangedCallback(string text)
        {
            UpdateInputFieldSuggestions();
        }
        private void OnAutoCompleteItemClickCallback(int index)
        {
            var realIndex = GetRealAutoCompleteIndex(index);
            SetSuggestionIndex(realIndex);
            AutoComplete();
            ui.ActivateInputField();
        }
        private void OnAutoCompleteArrowButtonClickCallback(bool up)
        {
            var direction = up ? -1 : 1;
            SetSuggestionIndex(Mathf.Clamp(suggestionIndex + direction * maxSuggestionCount, 0, currentSuggestions.Count - 1));
        }
        private void OnLogReceivedCallback(string logString, string stackTrace, LogType type)
        {
            lock (logLock)
            {
                switch (type)
                {
                    case LogType.Log:
                        return;
                    case LogType.Warning:
                        pendingLogs.Add($"<color=yellow>{logString}</color>\n");
                        return;
                    case LogType.Error:
                    case LogType.Exception:
                    case LogType.Assert:
                        pendingLogs.Add($"<color=red>{logString}</color>\n");
                        break;
                }
            }
        }

        private bool CheckSuggestionDirty()
        {
            var input = ui.GetCommand();
            var caret = ui.GetStringPosition();
            if (lastInput != input || lastCaret != caret)
            {
                lastInput = input;
                lastCaret = caret;
                return true;
            }
            return false;
        }
        private void UpdateInputFieldSuggestions()
        {
            // 输入变化时更新自动补全
            string command = ui.GetCommand();
            if (!historyNavigated && command != null && command.StartsWith(DebugManager.COMMAND_CHARACTER))
            {
                UpdateSuggestions(command, ui.GetStringPosition());
            }
            else
            {
                HideAutoCompletePanel();
            }
        }
        void HandleInputNavigation()
        {
            if (Main.InputManager.GetKeyDownOrHold(KeyCode.UpArrow))
            {
                PressUp();
                return;
            }

            if (Main.InputManager.GetKeyDownOrHold(KeyCode.DownArrow))
            {
                PressDown();
                return;
            }

            if (Input.GetKeyDown(KeyCode.Tab))
            {
                AutoComplete();
                return;
            }
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                Hide();
                return;
            }
        }
        void PressUp()
        {
            if (isAutoCompleteActive)
            {
                NavigateSuggestions(-1);
            }
            else
            {
                NavigateHistory(1);
            }
        }
        void PressDown()
        {
            if (isAutoCompleteActive)
            {
                NavigateSuggestions(1);
            }
            else
            {
                NavigateHistory(-1);
            }
        }

        private void FlushLogs()
        {
            lock (logLock)
            {
                if (pendingLogs.Count != 0)
                {
                    logWriteBuffer.AddRange(pendingLogs);
                    pendingLogs.Clear();
                }
            }
            foreach (var log in logWriteBuffer)
            {
                Print(log);
            }
            logWriteBuffer.Clear();
        }

        #region 自动补全
        private void NavigateSuggestions(int direction)
        {
            if (currentSuggestions.Count == 0)
                return;

            SetSuggestionIndex((suggestionIndex + direction + currentSuggestions.Count) % currentSuggestions.Count);
        }

        void UpdateSuggestions(string text, int currentIndex)
        {
            string input = text.Substring(0, currentIndex);
            string[] parts = Main.DebugManager.SplitCommand(input);
            if (parts.Length < 1)
                return;

            currentSuggestions.Clear();
            Main.DebugManager.FillSuggestions(parts, currentSuggestions);
            currentSuggestions.Sort();

            if (currentSuggestions.Count > 0)
            {
                suggestionIndex = 0;
                currentSuggestionViewStart = 0;
                ShowAutoCompletePanel();
                ui.SetAutoCompletePosition(currentIndex - parts[parts.Length - 1].Length);
            }
            else
            {
                HideAutoCompletePanel();
            }
        }

        void ShowAutoCompletePanel()
        {
            ui.ShowAutoCompletePanel();
            isAutoCompleteActive = true;

            UpdateAutoCompleteSelections();
            UpdateSelectedAutoComplete();
        }
        private void HideAutoCompletePanel()
        {
            ui.HideAutoCompletePanel();
            isAutoCompleteActive = false;
        }
        private void SetSuggestionIndex(int index)
        {
            suggestionIndex = index;

            bool dirty = false;
            if (suggestionIndex - suggestionMoveMargin < currentSuggestionViewStart && currentSuggestionViewStart > 0)
            {
                currentSuggestionViewStart = Mathf.Max(suggestionIndex - suggestionMoveMargin, 0);
                dirty = true;
            }
            var end = currentSuggestionViewStart + maxSuggestionCount;
            if (suggestionIndex + suggestionMoveMargin >= end && currentSuggestions.Count > end)
            {
                end = Mathf.Min(suggestionIndex + suggestionMoveMargin, currentSuggestions.Count);
                currentSuggestionViewStart = end - maxSuggestionCount;
                dirty = true;
            }
            if (dirty)
            {
                UpdateAutoCompleteSelections();
            }
            UpdateSelectedAutoComplete();
        }
        private void UpdateAutoCompleteSelections()
        {
            var suggestions = currentSuggestions.Skip(currentSuggestionViewStart).Take(maxSuggestionCount).ToArray();
            bool hasAbove = currentSuggestionViewStart > 0;
            bool hasBelow = currentSuggestionViewStart + maxSuggestionCount < currentSuggestions.Count - 1;
            ui.SetAutoCompleteSelections(suggestions, GetUIAutoCompleteIndex(suggestionIndex), hasAbove, hasBelow);
        }
        private void UpdateSelectedAutoComplete()
        {
            var uiIndex = GetUIAutoCompleteIndex(suggestionIndex);
            ui.SetCurrentAutoComplete(uiIndex);
        }
        private int GetRealAutoCompleteIndex(int uiIndex)
        {
            return uiIndex + currentSuggestionViewStart;
        }
        private int GetUIAutoCompleteIndex(int index)
        {
            return index - currentSuggestionViewStart;
        }

        private void AutoComplete()
        {
            if (currentSuggestions.Count == 0 || suggestionIndex < 0)
                return;

            var fullText = ui.GetCommand();
            var caretIndex = ui.GetStringPosition();
            var beforeText = fullText.Substring(0, caretIndex);
            var afterText = fullText.Substring(caretIndex);

            var splitedBefore = Main.DebugManager.SplitCommand(beforeText);
            var newBeforeText = string.Join(' ', splitedBefore.SkipLast(1));

            var completedText = currentSuggestions[suggestionIndex];
            if (!string.IsNullOrWhiteSpace(newBeforeText))
            {
                completedText = newBeforeText + " " + completedText;
            }
            completedText = DebugManager.COMMAND_CHARACTER + completedText;
            ui.SetCommand(completedText + afterText);
            ui.SetStringPosition(completedText.Length);

            UpdateInputFieldSuggestions();
        }
        #endregion

        #region 历史

        void SaveCommandHistory()
        {
            if (!keepHistoryBetweenSessions)
                return;
            Main.DebugManager.SaveCommandHistory(commandHistory);
        }

        void LoadCommandHistory()
        {
            if (!keepHistoryBetweenSessions)
                return;

            commandHistory.Clear();
            Main.DebugManager.LoadCommandHistory(commandHistory);
        }
        private void AddToHistory(string command)
        {
            // 避免添加重复的命令
            commandHistory.Remove(command);
            commandHistory.Insert(0, command);

            // 限制历史记录大小
            while (commandHistory.Count > maxHistorySize)
            {
                commandHistory.RemoveAt(commandHistory.Count - 1);
            }

            SaveCommandHistory();
        }
        private void NavigateHistory(int direction)
        {
            if (commandHistory.Count == 0)
                return;

            historyIndex = Mathf.Clamp(historyIndex + direction, -1, commandHistory.Count - 1);

            var command = string.Empty;
            if (historyIndex >= 0)
            {
                command = commandHistory[historyIndex];
            }
            ui.SetCommand(command);
            ui.MoveToCommandEnd(false);
            historyNavigated = true;
        }
        #endregion

        private void UpdateUIMargin()
        {
            ui.SetConsoleBottomMargin(GetKeyboardHeight() / Screen.height);
        }
        private float GetKeyboardHeight()
        {
            if (Application.isEditor)
            {
                return debugKeyboardHeight;
            }
            else if (Application.platform == RuntimePlatform.Android)
            {
                if (TouchScreenKeyboard.isSupported && TouchScreenKeyboard.visible)
                    return GetKeyboardHeightAndroid();
            }
            else if (Application.platform == RuntimePlatform.IPhonePlayer)
            {
                if (TouchScreenKeyboard.isSupported && TouchScreenKeyboard.visible)
                    return (float)TouchScreenKeyboard.area.height;
            }
            return 0f;
        }
        private float GetKeyboardHeightAndroid()
        {
            try
            {
                using AndroidJavaClass UnityClass = new AndroidJavaClass("com.unity3d.player.UnityPlayer");

                using AndroidJavaObject? currentActivity = UnityClass.GetStatic<AndroidJavaObject>("currentActivity");
                if (currentActivity == null)
                    return 0f;

                using AndroidJavaObject? mUnityPlayer = currentActivity.Get<AndroidJavaObject>("mUnityPlayer");
                if (mUnityPlayer == null)
                    return 0f;

                using AndroidJavaObject? view = mUnityPlayer.Call<AndroidJavaObject>("getView");
                if (view == null)
                    return 0f;

                using AndroidJavaObject rect = new AndroidJavaObject("android.graphics.Rect");

                view.Call("getWindowVisibleDisplayFrame", rect);
                return (float)(Screen.height - rect.Call<int>("height"));
            }
            catch (System.Exception e)
            {
                Debug.LogError("获取安卓窗口高度失败: " + e.Message);
                return 0f;
            }
        }
        public MainManager Main => MainManager.Instance;
        private List<string> commandHistory = new List<string>();
        private int historyIndex = -1;
        private List<string> currentSuggestions = new List<string>();
        private int currentSuggestionViewStart = 0;
        private int suggestionIndex;
        private bool isAutoCompleteActive;

        private string? lastInput;
        private int lastCaret = -1;
        private bool historyNavigated;
        private readonly List<string> pendingLogs = new List<string>();
        private readonly List<string> logWriteBuffer = new List<string>();
        private object logLock = new object();
        [SerializeField]
        private float debugKeyboardHeight = 0f;
        [SerializeField]
        private bool keepHistoryBetweenSessions = true;
        [SerializeField]
        private int maxHistorySize = 100;
        [SerializeField]
        private int suggestionMoveMargin = 1;
        [SerializeField]
        private int maxSuggestionCount = 10;
        [SerializeField]
        private DebugConsoleUI ui = null!;
    }
}
